sys_script_include.script:
var CaseUtility = Class.create();
CaseUtility.prototype = {

    initialize: function() {
    },

    getPriorityMessage: function(priority) {

        if (priority == 'p1_critical')
            return 'Critical Case';

        if (priority == 'p2_high')
            return 'High Priority Case';

        if (priority == 'p3_medium')
            return 'Medium Priority Case';

        return 'Low Priority Case';
    },

    type: 'CaseUtility'
};
